// This style of import is necessary for storybook to automatically generate the documentation for prop types
import * as React from "react";
import { useState, ChangeEvent, useEffect } from "react";
import { MpaIcon } from "../icon/MpaIcon";
import {SvgMpaIcon} from "../../assets/icons/index";
import { IconButton } from "../iconButton";
import "./QuantityToggle.scss";

export interface QuantityToggleProps {
  /**
   * Identifying value for the quantity toggle input.
   */
  id?: string;
  /**
   * label to be displayed above the quantity toggle input.
   */
  label?: string;
    /**
   * Hex code that determines the color of the increment and decrement buttons.
   */
  colour?: "primary" | "secondary" | "tertiary";
  /**
   * Initial value of the input field.
   */
  value: number;
  /**
   * Maximum value which the quantity toggle can reach.
   */
  maximumValue?: number;
  /**
   * Minimum value which the quantity toggle can reach.
   */
  minimumValue?: number;
  /**
   * Boolean which controls whether the component can be interacted with.
   */
  disabled: boolean;
  /**
   * Message to be displayed below the quantity toggle in case of an error.
   */
  errorMessage?: string;

  onChange?: (value: number) => void;
  /**
   * Text to be displayed in a help tooltip next to the label.
   */
  tooltipText?: string;
  /**
   * The placement of the overlay in relation to the icon.
   */
  tooltipPlacement?: "right" | "left" | "top" | "bottom";

  /**
   * SVG MPA Icon to be displayed beside lable for tooltip .
  */
  tooltipIcon?:  keyof typeof SvgMpaIcon | string;
  /**
   * Boolean which determines if the field must have a value.
   */
  required?: boolean;
}

export const QuantityToggle: React.FC<QuantityToggleProps> = ({
  id,
  label,
  value=0,
  maximumValue = 999999999,
  minimumValue = 0,
  disabled = false,
  errorMessage,  
  colour = "primary",
  onChange,
  tooltipText,
  tooltipPlacement="top",
  tooltipIcon,
  required = false,
}) => {
 const [count, setCount] = useState(value);
    useEffect(() => {
    if(minimumValue !== undefined && maximumValue !== undefined && minimumValue <= maximumValue) {      
     if (maximumValue !== undefined && count > maximumValue) {
        if (count !== maximumValue) {          
          setCount(maximumValue);
          onChange?.(maximumValue);          
        }
      }
    }
  }, [count, minimumValue, maximumValue]);

  useEffect(() => {        
    if(value <= maximumValue) {
      setCount(value);        
    } else if (value > maximumValue) {            
      setCount(maximumValue);
    }
  }, [value]);
  
  const handleInputChange = (event: ChangeEvent<HTMLInputElement>) => {
    const value = event.target.value.trim();
    if (value === "") {
      setCount(0);
      onChange?.(0);
    } else {
      const parsedValue = parseInt(value, 10);      
      if (!isNaN(parsedValue)) {
        if (maximumValue !== undefined && parsedValue > maximumValue) {          
          setCount(parsedValue);
          onChange?.(parsedValue);       
        } else {  
          setCount(parsedValue);
          onChange?.(parsedValue);
        }
      }
    }
  };

  const increment = () => {          
    if (maximumValue !== undefined) {            
      const newCount = Math.min(count + 1, maximumValue);      
      setCount(newCount);
      onChange?.(newCount);      
    } else {      
      setCount((prevCount) => {
        const updatedCount = prevCount + 1;
        onChange?.(updatedCount);
        return updatedCount;
      });
    }
  };
  
  const decrement = () => {     
     setCount((prevCount) => {
      const min = minimumValue ?? 0;
      const updatedCount = Math.max(prevCount - 1, min);
      onChange?.(updatedCount); 
      return updatedCount;
    });        
  };
 
  return (
    <div>      
        {label && tooltipText && tooltipText.trim().length > 0 && tooltipIcon ?(
            <label>
              {label}
              <span className={'quantity-label-tooltip-icon'}><MpaIcon colour="var(--mpa-gray)" 
                iconName={tooltipIcon} tooltipText={tooltipText} 
                tooltipPlacement={tooltipPlacement} /></span>
              {required ?(<span className={'quantity-label-required'}>*</span>
                ):(<span className={'quantity-label-optional'}>(Optional)</span>)}
            </label>
          ):(
          label &&
            <label>
              {label}
              {required ?(<span className={'quantity-label-required'}>*</span>):(<span className={'quantity-label-optional'}>(Optional)</span>)}
            </label>
          )
        }
       <div className="quantity-toggle-row">
        <IconButton 
            id={"quantity-decrement"} 
            colour={colour} 
            shape={"circle"} 
            size={"medium"}  
            icon={"Minus"}
            disabled={count === minimumValue || count === 0 || disabled }
            onClick={decrement}></IconButton>

        <div style={{ paddingLeft: "1rem", paddingRight: "1rem" }}>
            <input
              id={id}
              className={`quantity-input-text ${disabled ? "input-disabled" : ""}`}
              type="text"
              value={count}
              onChange={handleInputChange}
              disabled={disabled}
              aria-label="Quantity input"              
              autoComplete="off"
              style={{ borderColor: errorMessage ? "red" : "var(--mpa-gray-40)" }}
            />
        </div>

        <IconButton id={"quantity-decrement"} 
            colour={colour} 
            shape={"circle"} 
            size={"medium"}
            icon={"Plus"}
            disabled={disabled || (maximumValue !== undefined && count === maximumValue)} 
            onClick={increment}>
        </IconButton>
      </div>
      {errorMessage && (
        <div>
          <span className="error-icon"><MpaIcon iconName="AlertCircle" colour="var(--mpa-red-80)"/>
          <span className="error-text-padding">
          {errorMessage}
          </span>
          </span>
        </div>
      )}       
    </div>
  );
};

export default QuantityToggle;
